import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.3Jb79Omt.js";const c=JSON.parse('{"title":"搭建节点","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nodes.md","filePath":"guide/nodes.md","lastUpdated":1792126119000}'),o={name:"guide/nodes.md"};function l(i,t,n,s,h,b){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="搭建节点" tabindex="-1">搭建节点 <a class="header-anchor" href="#搭建节点" aria-label="Permalink to &quot;搭建节点&quot;">​</a></h1><p>在落地机上部署代理节点（入站）。所有配置由面板生成，节点上的 agent 只负责下载内核、写入配置、运行和守护进程。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ul><li>落地机已按 <a href="./install">安装部署</a> 装好节点 agent，并在面板里显示在线</li><li>Linux amd64 / arm64，root 权限</li><li>建议安装 nftables（<code>apt install nftables</code>）：入站流量统计、白名单和 Hysteria2 端口跳跃依赖它；没有 nftables 时节点照常工作，只是没有这些功能</li></ul><h2 id="安装内核" tabindex="-1">安装内核 <a class="header-anchor" href="#安装内核" aria-label="Permalink to &quot;安装内核&quot;">​</a></h2><p>入站页 → <strong>内核</strong> 标签 → <strong>安装内核</strong> → 选择节点和内核。</p><table tabindex="0"><thead><tr><th>内核</th><th>版本</th><th>说明</th></tr></thead><tbody><tr><td>Xray</td><td>默认最新版，可指定</td><td>从 GitHub Release 下载，用官方校验文件校验</td></tr><tr><td>sing-box</td><td>默认最新版，可指定</td><td>从 GitHub Release 下载，用 Release 资产的 SHA256 校验</td></tr><tr><td>Snell</td><td>5.0.1 / 4.1.1</td><td>只从官方 <code>dl.nssurge.com</code> 下载，使用内置的校验值</td></tr></tbody></table><p>一台节点可以同时安装多个内核，内核按节点分组显示。点击内核可以启停、重启、查看日志、更换版本或卸载；节点重启后内核会自动恢复运行。</p><h2 id="新建入站" tabindex="-1">新建入站 <a class="header-anchor" href="#新建入站" aria-label="Permalink to &quot;新建入站&quot;">​</a></h2><p>入站页 → <strong>入站</strong> 标签 → <strong>新建入站</strong> → 选择节点和内核 → 点击一个快速模板 → 填名称 → <strong>创建并下发</strong>。</p><p>端口留空会随机分配，UUID、密码、密钥留空会自动生成。</p><table tabindex="0"><thead><tr><th>模板</th><th>内核</th><th>说明</th></tr></thead><tbody><tr><td>VLESS + Reality + Vision</td><td>Xray / sing-box</td><td>推荐，无需域名和证书</td></tr><tr><td>VLESS + XHTTP + Reality</td><td>Xray</td><td></td></tr><tr><td>Shadowsocks 2022</td><td>Xray / sing-box</td><td></td></tr><tr><td>Trojan + TLS（自签）</td><td>Xray / sing-box</td><td>需要填写域名</td></tr><tr><td>VMess + WS + TLS</td><td>Xray / sing-box</td><td>兼容老客户端</td></tr><tr><td>Hysteria2</td><td>sing-box</td><td>基于 QUIC，可选端口跳跃</td></tr><tr><td>TUIC v5</td><td>sing-box</td><td>基于 QUIC</td></tr><tr><td>AnyTLS</td><td>sing-box</td><td></td></tr><tr><td>SS2022 + ShadowTLS</td><td>sing-box</td><td>仅 TCP</td></tr><tr><td>NaïveProxy</td><td>sing-box</td><td>需要域名和真实证书</td></tr><tr><td>Snell / Snell + ShadowTLS</td><td>Snell</td><td>Surge 专用</td></tr></tbody></table><h3 id="证书" tabindex="-1">证书 <a class="header-anchor" href="#证书" aria-label="Permalink to &quot;证书&quot;">​</a></h3><p>TLS 类入站有三种证书来源：</p><ul><li><strong>自动生成自签证书</strong>：开箱即用，客户端需要允许不安全证书（分享链接已自动带上）</li><li><strong>使用节点上的证书文件</strong>：填写证书和私钥在节点上的绝对路径</li><li><strong>自动申请证书（ACME）</strong>：仅 sing-box，需要 sing-box 1.14 及以上 <ul><li>域名必须解析到该节点</li><li>HTTP 验证：节点 80 端口要能从公网访问</li><li>DNS 验证：支持 Cloudflare（API Token）和阿里云（AccessKey），不需要 80 端口</li><li>证书由 sing-box 自动续期</li></ul></li></ul><p>NaïveProxy 必须使用真实证书（ACME 或证书文件）。</p><h3 id="hysteria2-端口跳跃" tabindex="-1">Hysteria2 端口跳跃 <a class="header-anchor" href="#hysteria2-端口跳跃" aria-label="Permalink to &quot;Hysteria2 端口跳跃&quot;">​</a></h3><p>在 Hysteria2 入站里填写一段 UDP 端口，例如 <code>20000-30000</code>。节点会用 nftables 把这段端口转到入站端口，客户端在其中随机切换，缓解运营商对单个 UDP 端口的限速。</p><ul><li>范围不能包含入站端口本身，不能和其他入站、转发或节点的转发端口段重叠</li><li>只有直连地址带跳跃参数；经中转连接时只转发一个端口，不跳跃</li></ul><h3 id="监听地址" tabindex="-1">监听地址 <a class="header-anchor" href="#监听地址" aria-label="Permalink to &quot;监听地址&quot;">​</a></h3><p>默认监听 <code>::</code>（同时支持 IPv4 和 IPv6）。如果节点在内核启动参数里完全禁用了 IPv6（<code>ipv6.disable=1</code>），部分内核会绑定失败，此时在高级选项里把监听地址改为 <code>0.0.0.0</code>。</p><h2 id="分享与订阅" tabindex="-1">分享与订阅 <a class="header-anchor" href="#分享与订阅" aria-label="Permalink to &quot;分享与订阅&quot;">​</a></h2><ul><li>点击入站 → <strong>分享</strong>（电脑上也可以直接点行内的“分享”按钮）：显示通用分享链接和二维码；Snell 没有通用链接，显示 Surge 配置行。Surge 用户请使用 Surge 订阅</li><li>入站页的 <strong>订阅</strong> 标签：包含所有已启用的入站和中转线路，客户端定期更新即可同步</li></ul><table tabindex="0"><thead><tr><th>订阅格式</th><th>适用客户端</th><th>不包含</th></tr></thead><tbody><tr><td>自动识别</td><td>按客户端 UA 返回对应格式</td><td></td></tr><tr><td>Clash / Mihomo</td><td>Clash Verge、Stash、FlClash</td><td>XHTTP、Snell、NaïveProxy</td></tr><tr><td>sing-box</td><td>SFA / SFI / SFM</td><td>XHTTP、Snell</td></tr><tr><td>通用 base64</td><td>v2rayN、Shadowrocket、NekoBox</td><td>Snell</td></tr><tr><td>Surge</td><td>Surge</td><td>VLESS、Reality、gRPC、XHTTP、NaïveProxy</td></tr></tbody></table><p>订阅链接可以在订阅标签里重置，旧链接随即失效。</p><p>下一步：<a href="./relay">对接中转</a></p>',26)])])}const u=d(o,[["render",l]]);export{c as __pageData,u as default};
